use std::fs
use std::env
use std::process

fn emit(t: string, number: bool, n: int) -> int {
    let mut k: int = n
    if number {
        for line in t.lines() {
            k += 1
            println("${k:>6}\t${line}")
        }
    } else {
        print(t)
    }
    k
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    for a in env::args() {
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut n: int = 0
    let mut failed = false
    if files.len() == 0 {
        n = emit(fs::read_to_string("/dev/stdin").unwrap_or(""), number, n)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => {
                    n = emit(t, number, n)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    failed = true
                }
            }
        }
    }
    if failed {
        process::exit(1)
    }
}
